export interface SerializedContext {
  messages: Message[]
  pendingToolCalls: { id: string; name: string; arguments: unknown }[]
  meta: { provider: Provider; model: string }
}
export function serializeContext(client: Client): SerializedContext
export function hydrateContext(client: Client, ctx: SerializedContext): void
// hydrateContext replays messages + pending tool calls into a fresh client of
// any provider; pendingToolCalls let you resume a tool round-trip across a swap.

import { createClient } from '@earendil-works/pi-ai'
export class AiSession {
  client = createClient({ provider: 'anthropic', model: 'claude-sonnet-4-6' })
  costUsd = 0
  async send(messages) { const s = await this.client.stream({ messages }); /* ... */ this.costUsd = this.client.usage.total.costUsd; return s }
}
// costUsd is mirrored from the client's usage meter after each send

