async handoff(provider, model) {
  const ctx = serializeContext(this.client)
  const carriedCost = this.costUsd
  const next = createClient({ provider, model })
  hydrateContext(next, ctx)
  this.client = next
  this.costBaseline = carriedCost   // running total survives the swap
  return { provider, model, pending: ctx.pendingToolCalls.length }
}

test('handoff preserves transcript and resumes a pending tool call', async () => {
  const s = new AiSession()
  await s.send([{ role: 'user', content: 'draw a box' }])  // anthropic, mid tool round-trip
  const r = await s.handoff('openai', 'gpt-4.1')
  expect(r.pending).toBe(1)
  expect(s.client.config.provider).toBe('openai')
  expect(serializeContext(s.client).messages.length).toBe(2)
})

test('running cost total carries across a handoff', async () => {
  const s = new AiSession()
  s.client.usage.__set({ costUsd: 0.12 })
  await s.handoff('openai', 'gpt-4.1')
  s.client.usage.__set({ costUsd: 0.05 })
  expect(s.costUsd).toBeCloseTo(0.17)
})
